resources.string:
pansou_template 格式示例：
{
  "data": {
    "merged_by_type": {
      "quark": [
        {
          "note": "电影名称",
          "url": "https://pan.quark.cn/xxx",
          "datetime": "2024-01-01"
        }
      ]
    }
  }
}

zreso_template 格式示例：
{
  "data": {
    "results": [
      {
        "title": "电影名称",
        "datetime": "2024-01-01",
        "links": [
          {
            "url": "https://pan.baidu.cn/xxx",
            "type": "baidu"
          }
        ]
      }
    ]
  }
}
